-- crash-edit/set-status
-- Publishes a crash (with its public slug) or takes it back to draft. Version-checked.
--
-- Parameters, with the example values used to render this file:
--   $1 = "2026-11-12-kathmandu-a1b2c3"
--   $2 = "published"
--   $3 = "0199c8a0-0000-7000-8000-00000000000a"
--   $4 = 2
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

update "crashes"
set "slug" = $1, "status" = $2, "version" = "crashes"."version" + 1, "updated_at" = now()
where ("crashes"."id" = $3
  and "crashes"."version" = $4)
returning "id", "slug", "status", "merged_into_id", "title_en", "title_np", "occurred_on", "occurred_time", "location", "location_precision", "place_name_en", "place_name_np", "province_id", "district_id", "local_unit_id", "deaths", "injured_total", "created_via", "verification_level", "version", "created_at", "updated_at";
